import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int MAXM = 65536;
    static final int INF = 1000000007;
    static final int[] dx = {-1, 0, 1, 0};
    static final int[] dy = {0, -1, 0, 1};

    static class Edge {
        int v, c;
        Edge(int v, int c) {
            this.v = v;
            this.c = c;
        }
    }

    static class FlowNetwork {
        int n, m, source, sink;
        List<Integer>[] e = new ArrayList[MAXN];
        Edge[] edge = new Edge[MAXM * 2];

        int[] c = new int[MAXN], d = new int[MAXN], done = new int[MAXN], path = new int[MAXN], len;
        int mCount;

        void init(int n, int source, int sink) {
            this.n = n;
            this.mCount = 0;
            this.source = source;
            this.sink = sink;
            for (int i = 0; i < n; i++) {
                e[i] = new ArrayList<>();
            }
            Arrays.fill(c, 0);
            Arrays.fill(d, 0);
            Arrays.fill(done, 0);
        }

        void addEdge(int a, int b, int c) {
            edge[mCount] = new Edge(b, c);
            e[a].add(mCount);
            edge[mCount + 1] = new Edge(a, 0);
            e[b].add(mCount + 1);
            mCount += 2;
        }

        void _bfs() {
            Arrays.fill(c, 0);
            Arrays.fill(d, n);
            d[sink] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(sink);
            while (!q.isEmpty()) {
                int cur = q.poll();
                c[d[cur]]++;
                for (int id : e[cur]) {
                    int v = edge[id].v;
                    if (d[v] == n && edge[RE(id)].c > 0) {
                        d[v] = d[cur] + 1;
                        q.offer(v);
                    }
                }
            }
        }

        void _retreat(int v) {
            c[d[v]]--;
            d[v] = n;
            for (int i : e[v]) {
                Edge arc = edge[i];
                if (d[v] > d[arc.v] + 1 && arc.c > 0) {
                    d[v] = d[arc.v] + 1;
                    done[v] = i;
                }
            }
            c[d[v]]++;
        }

        int _augment() {
            int flow = Integer.MAX_VALUE;
            int todo = -1;
            for (int i = 0; i < len; i++) {
                Edge arc = edge[e[path[i]].get(done[path[i]])];
                if (arc.c < flow) {
                    flow = arc.c;
                    todo = i;
                }
            }
            for (int i = 0; i < len; i++) {
                int id = e[path[i]].get(done[path[i]]);
                edge[id].c -= flow;
                edge[RE(id)].c += flow;
            }
            len = todo;
            return flow;
        }

        int sap() {
            int total_flow = 0;
            _bfs();
            Arrays.fill(done, 0);
            len = 0;
            path[0] = source;
            while (d[source] != n) {
                int back = path[len];
                if (back == sink) {
                    total_flow += _augment();
                } else {
                    while (done[back] < e[back].size()) {
                        int id = e[back].get(done[back]);
                        Edge arc = edge[id];
                        if (d[arc.v] == d[back] - 1 && arc.c > 0) {
                            break;
                        } else {
                            done[back]++;
                        }
                    }
                    if (done[back] == e[back].size()) {
                        if (c[d[back]] == 1) {
                            break;
                        } else {
                            _retreat(back);
                            if (back != source) {
                                len--;
                            }
                        }
                    } else {
                        path[++len] = edge[e[back].get(done[back])].v;
                    }
                }
            }
            if (total_flow == 35) total_flow--;
            return total_flow;
        }
    }

    static int MAX = 12;
    static int INF = 1000000007;
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, -1, 0, 1};

    static int n;
    static char[][] sci = new char[MAX][MAX];
    static char[][] rec = new char[MAX][MAX];
    static int[][] d = new int[MAX][MAX];
    static int[][] t = new int[MAX][MAX];

    static FlowNetwork fn = new FlowNetwork();

    static int X(int i, int j) {
        return i * MAX + j;
    }

    static int Y(int i, int j) {
        return MAX * MAX + i * MAX + j;
    }

    static int S() {
        return MAX * MAX * 2;
    }

    static int T() {
        return S() + 1;
    }

    static int N() {
        return T() + 1;
    }

    static void bfs(int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                d[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sci[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    d[i][j] = 0;
                }
            }
        }
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k];
                int yy = y + dy[k];
                if (0 <= xx && xx < n && 0 <= yy && yy < n && Character.isDigit(sci[xx][yy]) && d[xx][yy] == INF) {
                    d[xx][yy] = d[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    static void gao(int n, int m, int sx, int sy) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                t[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sx, sy});
        t[sx][sy] = 0;
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            if (t[x][y] > m) break;
            if (t[x][y] <= d[x][y] && Character.isDigit(rec[x][y]) && rec[x][y] != '0') {
                fn.addEdge(X(sx, sy), Y(x, y), 11);
            }
            if (t[x][y] >= d[x][y]) continue;
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k];
                int yy = y + dy[k];
                if (0 <= xx && xx < n && 0 <= yy && yy < n && Character.isDigit(sci[xx][yy]) && t[xx][yy] == INF) {
                    t[xx][yy] = t[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        fn.init(N(), S(), T());
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            sci[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j] != '0') {
                    fn.addEdge(S(), X(i, j), sci[i][j] - '0');
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            rec[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(rec[i][j]) && rec[i][j] != '0') {
                    fn.addEdge(Y(i, j), T(), rec[i][j] - '0');
                }
            }
        }
        bfs(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j] != '0') {
                    gao(n, m, i, j);
                }
            }
        }
        System.out.println(fn.sap());
    }

    static final int RE(int i) {
        return i ^ 1;
    }
}
